import Capacitor
import UIKit
import WebKit

/// Registers the local Sign in with Apple plugin. Package.swift is generated by cap sync.
/// The iOS binary never sends the Samsung or Huawei store token.
/// Dynamic Type writes --ke-text-scale so larger system text grows the layout.
class KidEaseBridgeViewController: CAPBridgeViewController {
    private var textScaleScript: WKUserScript?
    override open func instanceDescriptor() -> InstanceDescriptor {
        let descriptor = super.instanceDescriptor()
        descriptor.appendedUserAgentString = Self.withoutForeignStoreToken(descriptor.appendedUserAgentString)
        descriptor.overridenUserAgentString = Self.withoutForeignStoreToken(descriptor.overridenUserAgentString)
        if let server = descriptor.serverURL {
            descriptor.serverURL = Self.withoutSamsungStoreQuery(server)
        }
        return descriptor
    }

    override open func capacitorDidLoad() {
        super.capacitorDidLoad()
        bridge?.registerPluginInstance(AppleSignInPlugin())
        if let controller = webView?.configuration.userContentController {
            installTextScaleScript(on: controller)
        }
        NotificationCenter.default.addObserver(
            self,
            selector: #selector(contentSizeChanged),
            name: UIContentSizeCategory.didChangeNotification,
            object: nil
        )
    }

    deinit {
        NotificationCenter.default.removeObserver(self)
    }

    /// Fold, unfold, rotation, and iPad Split View change the window size.
    /// The web view follows Auto Layout. Reloading here would drop a call.
    override open func viewWillTransition(to size: CGSize, with coordinator: UIViewControllerTransitionCoordinator) {
        super.viewWillTransition(to: size, with: coordinator)
    }

    @objc private func contentSizeChanged() {
        if let controller = webView?.configuration.userContentController {
            installTextScaleScript(on: controller)
        }
        applyTextScale()
    }

    /// Larger than Large grows the root font. Large stays at the current 14px design.
    static func textScale(for category: UIContentSizeCategory) -> String {
        switch category {
        case .extraSmall: return "0.82"
        case .small: return "0.88"
        case .medium: return "0.94"
        case .large: return "1"
        case .extraLarge: return "1.12"
        case .extraExtraLarge: return "1.23"
        case .extraExtraExtraLarge: return "1.35"
        case .accessibilityMedium: return "1.50"
        case .accessibilityLarge: return "1.64"
        case .accessibilityExtraLarge: return "1.79"
        case .accessibilityExtraExtraLarge: return "1.93"
        case .accessibilityExtraExtraExtraLarge: return "2.12"
        default: return "1"
        }
    }

    private func installTextScaleScript(on controller: WKUserContentController) {
        if let old = textScaleScript {
            controller.removeUserScript(old)
        }
        let scale = Self.textScale(for: UIApplication.shared.preferredContentSizeCategory)
        let source = "document.documentElement.style.setProperty('--ke-text-scale','\(scale)');"
        let script = WKUserScript(source: source, injectionTime: .atDocumentStart, forMainFrameOnly: true)
        controller.addUserScript(script)
        textScaleScript = script
    }

    private func applyTextScale() {
        let scale = Self.textScale(for: UIApplication.shared.preferredContentSizeCategory)
        webView?.evaluateJavaScript("document.documentElement.style.setProperty('--ke-text-scale','\(scale)')")
    }

    /// KidEaseStoreSamsung belongs to the Galaxy Store flavour only.
    static func withoutForeignStoreToken(_ agent: String?) -> String? {
        guard let agent else { return nil }
        let cleaned = agent
            .replacingOccurrences(of: "KidEaseStoreSamsung", with: "")
            .replacingOccurrences(of: "KidEaseStoreHuawei", with: "")
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return cleaned.isEmpty ? nil : cleaned
    }

    static func withoutSamsungStoreQuery(_ raw: String) -> String {
        guard var parts = URLComponents(string: raw), let items = parts.queryItems else { return raw }
        let next = items.filter { !($0.name == "store" && $0.value == "samsung") }
        if next.count == items.count { return raw }
        parts.queryItems = next.isEmpty ? nil : next
        return parts.string ?? raw
    }
}
